        "texto": "Interesse de agir se verifica pela necessidade (o provimento jurisdicional é indispensável para a satisfação do direito, não havendo outro meio disponível) combinada com a adequação (o procedimento e o pedido escolhidos são compatíveis com a pretensão deduzida) — faltando qualquer um desses dois aspectos, falta interesse processual."
